	/**
	 * Default Constructor
	 */
    public InspectionResultService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new InspectionResultEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(InspectionResultRepository.class) );
		this.validator		= applicationContext.getBean(InspectionResultValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		InspectionResult
	 */
		public InspectionResult createInspectionResult( CreateInspectionResultCommand command ) {

		InspectionResult entity = new InspectionResult();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setInspectionResultId( command.getInspectionResultId() );
            entity.setResultValue( command.getResultValue() );
            entity.setRecordedOn( command.getRecordedOn() );
            entity.setNotes( command.getNotes() );
            entity.setResultStatus( command.getResultStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of InspectionResult {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateInspectionResultCommand
	 * @return		InspectionResult
	 */
	public InspectionResult updateInspectionResult( UpdateInspectionResultCommand command ) {

		InspectionResult entity = new InspectionResult();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setInspectionResultId( command.getInspectionResultId() );
            entity.setResultValue( command.getResultValue() );
            entity.setRecordedOn( command.getRecordedOn() );
            entity.setNotes( command.getNotes() );
            entity.setInspectionLot( command.getInspectionLot() );
            entity.setCharacteristic( command.getCharacteristic() );
            entity.setResultStatus( command.getResultStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of InspectionResult {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteInspectionResultCommand
	 */
	public void delete( DeleteInspectionResultCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getInspectionResultId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of InspectionResult {0} ", id );

	}

	/**
	 * Method to retrieve the InspectionResult via InspectionResultFetchOneSummary
	 * @param 	summary InspectionResultFetchOneSummary
	 * @return 	InspectionResultFetchOneResponse
	 */
	public InspectionResult getInspectionResult( InspectionResultFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "InspectionResultFetchOneSummary arg cannot be null" );

		InspectionResult entity = null;
		UUID id = summary.getInspectionResultId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a InspectionResult using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all InspectionResults
	 *
	 * @return 	List<InspectionResult>
	 */
    public List<InspectionResult> getAllInspectionResult() {
		List<InspectionResult> list = projector.findAll( new FindAllInspectionResultQuery() );
		return list;
	}

	/**
	 * assign InspectionLot on InspectionResult
	 * @param		command AssignInspectionLotToInspectionResultCommand
	 */
	public void assignInspectionLot( AssignInspectionLotToInspectionResultCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignInspectionLot(command.getInspectionResultId(), command.getAssignment());

	}

